class InputCell(_Cell):
    def __init__(self, initial_value):
        super().__init__()
        self._value = initial_value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        if new_value == self._value:
            return
        self._value = new_value
        self._propagate()

    def _propagate(self):
        # Collect every transitively dependent compute cell.
        affected = {}
        stack = list(self._dependents)
        while stack:
            cell = stack.pop()
            if id(cell) not in affected:
                affected[id(cell)] = cell
                stack.extend(cell._dependents)
        # Recompute in dependency order so each cell is evaluated once.
        ordered = sorted(affected.values(), key=lambda c: c.level)
        old_values = [(cell, cell._value) for cell in ordered]
        for cell in ordered:
            cell._recompute()
        # Notify only after reaching a stable state.
        for cell, old in old_values:
            if cell._value != old:
                for callback in list(cell._callbacks):
                    callback(cell._value)


class ComputeCell(_Cell):
    def __init__(self, inputs, compute_function):
        super().__init__()
        self._inputs = list(inputs)
        self._compute_function = compute_function
        self._callbacks = []
        self.level = 1 + max((cell.level for cell in self._inputs), default=0)
        for cell in self._inputs:
            cell._dependents.append(self)
        self._recompute()

    def _recompute(self):
        self._value = self._compute_function([cell.value for cell in self._inputs])

    def add_callback(self, callback):
        if callback not in self._callbacks:
            self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)
